    mins = {col: ws.cell(row=20, column=col).value for col in range(2, 7)}
    maxs = {col: ws.cell(row=21, column=col).value for col in range(2, 7)}

    # data rows 2..18
    for r in range(2, 19):
        residual = ws.cell(row=r, column=9).value
        if residual is None:
            continue
        remaining = abs(residual)
        if residual < 0:
            # deficit -> ADD units, order unit1(2) .. unit5(6)
            order = [2, 3, 4, 5, 6]
            for col in order:
                cur = ws.cell(row=r, column=col).value
                if cur is None or cur == 0:
                    continue
                room = maxs[col] - cur
                delta = min(remaining, room)
                ws.cell(row=r, column=col).value = cur + delta
                remaining -= delta
                if remaining <= 0:
                    break
        else:
            # surplus -> SUBTRACT units, order unit5(6) .. unit1(2)
            order = [6, 5, 4, 3, 2]
            for col in order:
                cur = ws.cell(row=r, column=col).value
                if cur is None or cur == 0:
                    continue
                room = cur - mins[col]
                delta = min(remaining, room)
                ws.cell(row=r, column=col).value = cur - delta
                remaining -= delta
                if remaining <= 0:
                    break
        # balance the residual to 0 at the end
        ws.cell(row=r, column=9).value = 0

